```css
/* IconButton — from the tokenloom snapshot's only component set ("IconButton").
   Note: despite the name, the base root contains three children — icon (100:2),
   text label "Save" (100:6) and chevron (100:7) — so this is rendered as
   icon + label + chevron, per the design context rather than the name.
   Every colour, space, radius and typography value below is a token var from
   tokensUsed; icon boxes are sized in `em` so they track the label typography
   token instead of introducing a literal dimension. */

.iconbutton {
  display: inline-flex;
  flex-direction: row;          /* root layout.dir: row */
  align-items: center;          /* crossAlign: center */
  justify-content: center;      /* align: center */
  width: fit-content;           /* sizing.w: hug */
  height: fit-content;          /* sizing.h: hug */
  gap: var(--space-xs);         /* base layout.gap: space.xs */
  padding: var(--space-sm) var(--space-md) var(--space-sm) var(--space-md);
  background: var(--color-action-bg);
  border-radius: var(--radius-md);
  border: none;
  color: var(--color-action-fg);
  font-family: var(--typo-label-md-font-family);
  font-size: var(--typo-label-md-font-size);
  font-weight: var(--typo-label-md-font-weight);
  line-height: var(--typo-label-md-line-height);
  cursor: pointer;
}

/* children */
.iconbutton__icon,
.iconbutton__chevron {
  display: inline-flex;
  flex: none;                   /* sizing: hug / hug */
  width: 1em;
  height: 1em;
  color: currentColor;
}

.iconbutton__icon svg,
.iconbutton__chevron svg {
  width: 100%;
  height: 100%;
  display: block;
  fill: currentColor;
}

.iconbutton__label {
  flex: none;                   /* sizing: hug / hug */
  color: var(--color-action-fg);
  font-family: var(--typo-label-md-font-family);
  font-size: var(--typo-label-md-font-size);
  font-weight: var(--typo-label-md-font-weight);
  line-height: var(--typo-label-md-line-height);
  white-space: nowrap;
}

/* size variants — only /layout/gap differs */
.iconbutton--size-sm { gap: var(--space-xs); }
.iconbutton--size-md { gap: var(--space-sm); }
.iconbutton--size-lg { gap: var(--space-md); }

/* state variants — only /style/bg differs */
.iconbutton--state-default  { background: var(--color-action-bg); }
.iconbutton--state-hover    { background: var(--color-action-border); }
.iconbutton--state-disabled { background: var(--color-surface-muted); }

/* live interaction mirroring the hover / disabled variants */
.iconbutton:not(.iconbutton--state-disabled):not([disabled]):hover {
  background: var(--color-action-border);
}

.iconbutton--state-disabled,
.iconbutton[disabled] {
  background: var(--color-surface-muted);
  cursor: default;
  pointer-events: none;
}
